    fn wire_label(&mut self)->Result<WireEdgeLabel,TextError>{self.expect(TokenKind::LBracket)?;let id=if self.kind()?==TokenKind::Ident{let token=self.take()?;Some(self.copy(token.text)?)}else{None};let kind=if self.kind()?==TokenKind::Colon{self.take()?;let token=self.expect(TokenKind::Ident)?;Some(self.copy(token.text)?)}else{None};if id.is_none()&&kind.is_none(){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native wire label requires an identity or kind"));}self.expect(TokenKind::RBracket)?;Ok(WireEdgeLabel{id,kind})}
    fn wire(&mut self,depth:usize)->Result<WireValue,TextError>{
        let mut from=self.wire_node()?;let mut edge_label=WireEdgeLabel::default();let token=self.peek(0)?;
        let edge=match token.kind{
            TokenKind::Arrow|TokenKind::DashArrow=>{self.take()?;Some((token.kind==TokenKind::Arrow,self.wire_node()?))},
            TokenKind::BackArrow=>{self.take()?;if self.kind()?==TokenKind::LBracket{edge_label=self.wire_label()?;self.expect(TokenKind::Minus)?;}let to=self.wire_node()?;Some((true,std::mem::replace(&mut from,to)))},
            TokenKind::Minus if self.peek(1)?.kind==TokenKind::LBracket=>{self.take()?;edge_label=self.wire_label()?;let arrow=self.take()?;if !matches!(arrow.kind,TokenKind::Arrow|TokenKind::DashArrow){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native wire label requires an arrow"));}Some((arrow.kind==TokenKind::Arrow,self.wire_node()?))},
            TokenKind::EdgeArrow=>{self.take()?;let body=&token.text[1..token.text.len()-1];let(id,kind)=if let Some(kind)=body.strip_prefix(':'){(None,Some(kind))}else if let Some((id,kind))=body.split_once(':'){(Some(id),Some(kind))}else{(Some(body),None)};edge_label=WireEdgeLabel{id:id.map(|value|self.copy(value)).transpose()?,kind:kind.map(|value|self.copy(value)).transpose()?};Some((token.text.ends_with('>'),self.wire_node()?))},
            _=>None
        };
