    }
    fn fixed_numbers(&mut self,count:usize)->Result<FieldValue,TextError>{let mut values=Vec::new();for index in 0..count{if index!=0{self.expect(TokenKind::Comma)?;}let(value,_)=self.number()?;self.push(&mut values,FieldValue::Float(value))?;}if self.kind()?==TokenKind::Comma{return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native coordinate arity mismatch"));}Ok(FieldValue::Tuple(values))}
    fn table(&mut self,make:RecordSpecProducer,depth:usize)->Result<FieldValue,TextError>{
        let spec=self.metadata(&make)?;validate_table_columns(&spec)?;self.expect(TokenKind::LBracket)?;let mut columns=Vec::new();while self.kind()?!=TokenKind::RBracket{let token=self.expect(TokenKind::Ident)?;let field=spec.fields.iter().find(|field|field.key==token.text).ok_or_else(||self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown native table column"))?;if columns.iter().any(|column:&&FieldSpec|column.id==field.id){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"duplicate native table column"));}if self.kind()?==TokenKind::Colon{self.take()?;self.expect(TokenKind::Ident)?;}self.push(&mut columns,field)?;}self.take()?;self.expect(TokenKind::LBrace)?;let mut rows=Vec::new();while self.kind()?!=TokenKind::RBrace{if columns.is_empty(){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native table requires columns"));}self.node(depth)?;let mut record=RecordValue::default();for field in &columns{let value=if self.kind()?==TokenKind::Placeholder{self.take()?;FieldValue::Absent}else if let Shape::Record(make)=field.shape{self.expect(TokenKind::LBrace)?;let record={let spec=self.metadata(&make)?;self.record(&spec,depth+1)?};self.expect(TokenKind::RBrace)?;FieldValue::Record(record)}else{self.shape(&field.shape,depth+1)?};self.insert(&mut record,field.id,value)?;}for field in &spec.fields{if !record.fields.contains_key(&field.id){self.insert(&mut record,field.id,FieldValue::Absent)?;}}self.push(&mut rows,FieldValue::Record(record))?;}self.take()?;Ok(FieldValue::List(rows))
    }
    fn dynamic(&mut self,depth:usize)->Result<DslValue,TextError>{
        self.node(depth)?;let token=self.peek(0)?;match token.kind{
            TokenKind::LBrace=>{self.take()?;let mut entries=Vec::new();while let Some(key)=self.dynamic_key()?{let key=self.text(key)?;self.take()?;self.expect(TokenKind::Equals)?;let value=self.dynamic(depth+1)?;self.push(&mut entries,(key,value))?;}self.expect(TokenKind::RBrace)?;Ok(DslValue::Object(entries))},
            TokenKind::LBracket=>{self.take()?;let mut values=Vec::new();while self.kind()?!=TokenKind::RBracket{let value=self.dynamic(depth+1)?;self.push(&mut values,value)?;}self.take()?;Ok(DslValue::Array(values))},
            TokenKind::Text=>{self.take()?;self.text(token).map(DslValue::String)},
            TokenKind::Int=>{self.take()?;if token.text.len()>2048{return Err(self.error(semio_framework_value::ValueRefusalKind::WorkLimit,"native dynamic integer is too long"));}let value=if let Ok(value)=token.text.parse::<u64>(){Number::UInt(value)}else if let Ok(value)=token.text.parse::<i64>(){Number::Int(value)}else{Number::Float(parse_f64(token.text).map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic number"))?)};Ok(DslValue::Number(value))},
            TokenKind::Float=>self.number().map(|(value,_)|DslValue::Number(Number::Float(value))),
            TokenKind::Ident=>{self.take()?;match token.text{"null"=>Ok(DslValue::Null),"true"=>Ok(DslValue::Bool(true)),"false"=>Ok(DslValue::Bool(false)),"nan"|"inf"=>parse_f64(token.text).map(|value|DslValue::Number(Number::Float(value))).map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic number")),"int64"=>{self.expect(TokenKind::LParen)?;let token=self.expect(TokenKind::Int)?;if token.text.len()>21{return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native signed integer is out of range"))}let value=token.text.parse::<i64>().map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native signed integer"))?;self.expect(TokenKind::RParen)?;Ok(DslValue::Number(Number::Int(value)))},"bytes64"=>{self.expect(TokenKind::LParen)?;let token=self.expect(TokenKind::Text)?;let bytes=self.octets(token)?;self.expect(TokenKind::RParen)?;Ok(DslValue::Bytes(bytes))},_=>Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown native dynamic literal"))}},
            _=>Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic value"))
        }
    }
    fn expression(&mut self,minimum:u8,depth:usize)->Result<ExprValue,TextError>{
        self.node(depth)?;let token=self.peek(0)?;let left=match token.kind{
            TokenKind::Minus=>{self.take()?;self.charge(size_of::<ExprValue>())?;ExprValue::Neg(Box::new(self.expression(3,depth+1)?))},
            TokenKind::LParen=>{self.take()?;let value=self.expression(0,depth+1)?;self.expect(TokenKind::RParen)?;value},
            TokenKind::Ident|TokenKind::Text if token.kind==TokenKind::Text||!matches!(token.text,"inf"|"nan")=>{self.take()?;let name=if token.kind==TokenKind::Text{self.text(token)?}else{self.copy(token.text)?};if self.kind()?==TokenKind::LParen{self.take()?;let mut values=Vec::new();if self.kind()?!=TokenKind::RParen{loop{let value=self.expression(0,depth+1)?;self.push(&mut values,value)?;if self.kind()?!=TokenKind::Comma{break;}self.take()?;}}self.expect(TokenKind::RParen)?;ExprValue::Call(name,values)}else{ExprValue::Var(name)}},
            _=>ExprValue::Num(self.number()?.0)
        };
        self.expression_tail(left,minimum,depth)
    }
    fn expression_tail(&mut self,mut left:ExprValue,minimum:u8,depth:usize)->Result<ExprValue,TextError>{
        let mut count=0usize;
        loop{let token=self.peek(0)?;let glued=matches!(token.kind,TokenKind::Int|TokenKind::Float)&&token.text.starts_with('-');let operator=if glued{Some(ExprOp::Sub)}else{match token.kind{TokenKind::Plus=>Some(ExprOp::Add),TokenKind::Minus=>Some(ExprOp::Sub),TokenKind::Star=>Some(ExprOp::Mul),TokenKind::Slash=>Some(ExprOp::Div),_=>None}};let Some(operator)=operator else{break;};let precedence=operator.precedence();if precedence<minimum{break;}count+=1;self.node(depth+count)?;self.charge(size_of::<ExprValue>()*2)?;let right=if glued{let value=ExprValue::Num(-self.number()?.0);self.expression_tail(value,precedence+1,depth+1)?}else{self.take()?;self.expression(precedence+1,depth+1)?};left=ExprValue::Binary(operator,Box::new(left),Box::new(right));}Ok(left)
    }
}

/// 🧭️ Parses exact schema-owned Text with bounded borrowed scanning, cumulative ownership and interior cancellation.
pub fn parse_exact_controlled(text:&str,spec:&RecordSpec,options:&ParseOptions,control:&mut NativeDecodeControl<'_>)->Result<Cst,TextError>{
    options.limits.check_bytes(text.len())?;
    control.scoped_stage(|control|{control.begin_stage(text.len()).map_err(|error|TextError::from_value_error(error,TextSpan::at(1,1)))?;let mut reader=Reader{source:text,position:0,line:1,column:1,lookahead:[None,None],limits:options.limits,tokens:0,nodes:0,control};let record=reader.record(spec,0)?;reader.expect(TokenKind::Eof)?;Ok(record)})
}

/// 🧮️ Parses a bare semantic expression under the same owned native allocation and input work control.
pub fn parse_expr_text_controlled(text:&str,limits:&Limits,control:&mut NativeDecodeControl<'_>)->Result<ExprValue,TextError>{limits.check_bytes(text.len())?;control.scoped_stage(|control|{control.begin_stage(text.len()).map_err(|error|TextError::from_value_error(error,TextSpan::at(1,1)))?;let mut reader=Reader{source:text,position:0,line:1,column:1,lookahead:[None,None],limits:*limits,tokens:0,nodes:0,control};let value=reader.expression(0,0)?;reader.expect(TokenKind::Eof)?;Ok(value)})}
